add_filter( 'woocommerce_available_payment_gateways', 'perfectpixel_disable_gateway_by_category' );

function perfectpixel_disable_gateway_by_category( $gateways ) {
	if ( is_admin() || ! WC()->cart ) {
		return $gateways;
	}
	$slugs = array_filter( array_map( 'trim', explode( ',', '{{gateway_category_slugs}}' ) ) );
	$found = false;
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( has_term( $slugs, 'product_cat', $item['product_id'] ) ) {
			$found = true;
			break;
		}
		// Sub-categories of the chosen categories count too.
		foreach ( wp_get_post_terms( $item['product_id'], 'product_cat', array( 'fields' => 'ids' ) ) as $term_id ) {
			foreach ( get_ancestors( $term_id, 'product_cat', 'taxonomy' ) as $ancestor ) {
				$term = get_term( $ancestor, 'product_cat' );
				if ( $term && in_array( $term->slug, $slugs, true ) ) {
					$found = true;
					break 3;
				}
			}
		}
	}
	if ( $found ) {
		foreach ( array_filter( array_map( 'trim', explode( ',', '{{gateway_category_disable}}' ) ) ) as $id ) {
			unset( $gateways[ $id ] );
		}
	}
	return $gateways;
}
